// Hybrid execution engine: persisted pause state shape. Carries everything
// the hybrid loop needs to rehydrate on resume (delay-step, ask_user, or
// hitl_approval).
export interface HybridResumeState {
  kind: 'hybrid-pause';
  pauseReason: 'delay' | 'ask_user' | 'hitl_approval' | 'delegation' | 'self_wake';
  /** Concrete engine that owned the run when it paused, resolved from the
   *  run's provider + engine env flags at pause time. Read on resume to detect
   *  a deployment whose flags now resolve a DIFFERENT engine than the one that
   *  produced a persisted native artifact (SDK session / adapter resume token):
   *  reconstructing the wrong adapter cannot consume that artifact. Optional for
   *  back-compat with pauses persisted before this field — an absent value is
   *  treated as unknown-legacy and never hard-fails a resume. */
  executionEngine?: ExecutionEngineId;
  currentStepId: string;
  resumeAfterStepId: string | null;
  stepOutput: unknown;
  /** The options offered with an ask_user question, when it had any.
   *  Carried so the resume can expand a bare "2" into the label the person
   *  actually meant; without it the agent gets a naked number in a fresh turn
   *  and has to guess what it referred to. */
  clarifyChoices?: Array<{ label: string; value: string; description?: string }>;
  clarifyMultiSelect?: boolean;
  /** The original run objective, captured at pause time so the resume re-enters
   *  with the real task — NOT the resume trace-label. Without this, conversational
   *  resume feeds the trace-label ('hitl-approved-resume' etc.) into the system
   *  prompt's "## Current Objective", the skill-retrieval query, and the initial
   *  user turn. Optional for back-compat with pauses persisted before this field. */
  objective?: string;
  /** The original run's triggerKey, captured at pause time so a HITL resume can
   *  load the persisted autonomous SDK session (keyed by triggerKey) and resume
   *  the EXACT structured conversation rather than the flattened-text snapshot
   *  replay. Only meaningful when AUTONOMOUS_RESUME_ENABLED was on for the run
   *  (so a session was saved). Optional for back-compat. */
  triggerKey?: string;
  /** The run's workflow and task ids, persisted with the pause for the same
   *  reason `trigger` is: the resume is rebuilt from a task body that does not
   *  carry them, and both feed uuid columns downstream where only a real id or
   *  NULL is valid. Stamped by `carryTriggerOntoPause` off the live context;
   *  never a blank. Optional for back-compat — a pause persisted before this
   *  field recovers them from its approval row instead. */
  workflowId?: string;
  taskId?: string;
  /** The account that originated the run (a chat turn's sender), persisted
   *  with the pause because a resume is rebuilt from a task body that carries
   *  no account. An own-account capability resolves the tenant's connected
   *  connector THROUGH this account; without it the executor cannot find the
   *  connection and refuses, so a person approves a send that never happens.
   *  Provenance is the live context at pause time — never the task body or the
   *  model. Optional for back-compat. */
  messageSenderAccountId?: string;
  inputData: Record<string, unknown> | undefined;
  /** What woke the run, persisted with the pause.
   *
   *  `resumeFromHitlApproval` already rebuilds the context with
   *  `trigger: context.trigger`, and the comment there explains at length why a
   *  rebuild that drops the trigger turns every acknowledgement into an
   *  approval request. That half was right and reached nothing: the ONLY caller
   *  is the Cloud Tasks handler's `minimalContext`, which is built from the
   *  task body — tenantId, agentId, invocationId — and has never carried a
   *  trigger. So the receiving end read a field the sending end could not set,
   *  and `state.context.trigger` was undefined on every HITL resume in
   *  production.
   *
   *  It cannot be reconstructed at resume time either: the task body is written
   *  by the approval router, which knows the approval, not the connector event.
   *  The only moment both facts are in hand is the pause. Hence: persisted here,
   *  by `createHitlPause`, off the live `state.context`.
   *
   *  Two consumers, and both fail SILENTLY without it — which is why this was
   *  invisible for so long. `buildTriggerTarget` returns undefined, so
   *  `isInPlaceReply` returns false on its first line and the resumed run gates
   *  again on work a human just approved. And the trigger-bound rewrite below
   *  has no `triggerSource`, so `trigger__<op>` reaches dispatch as a literal
   *  connector alias named `trigger`.
   *
   *  Optional for back-compat with pauses persisted before this field; an
   *  absent value resumes exactly as it does today. */
  trigger?: AgentTrigger;
  /** Trust level cached off `trigger`, carried for the same reason. It decides
   *  whether the external-content invariant applies to the resumed half at all,
   *  so losing it silently relaxes the gate rather than tightening it. */
  trustLevel?: 'trusted' | 'untrusted_inbound';
  /** The provider and model the paused half ran on, at the top level so a
   *  wake, delegation or clarification pause shares what the HITL pause keeps
   *  in `hitlContext`. A wake continuation resolves the pair from here rather
   *  than from whatever the hire is configured with when the trigger fires.
   *  Optional for back-compat: a payload without them takes the fresh-task
   *  path (`legacy_fallback`). */
  provider?: ResolvedProvider;
  model?: string;
  /** The canonical transcript at pause time, in the same shape
   *  `hitlContext.conversationHistory` uses. For a conversational run it is the
   *  run's history; for a workflow adapter step it is that step's own turn. It
   *  ends with the wake-producing call and its marker result, so the resumed
   *  model sees the wait as done. Restored ONCE by the continuation and never
   *  appended to a history the task would otherwise rebuild. Optional for
   *  back-compat, same rule as `provider`. */
  conversationHistory?: Array<{
    role: 'user' | 'assistant' | 'tool';
    content: string;
    toolCallId?: string;
    toolName?: string;
    toolCalls?: Array<{ id: string; name: string; input: Record<string, unknown> }>;
  }>;
  /** The canonical transcript checkpointed WITH this pause (migration 414,
   *  pause-checkpoint.ts): the row it wrote, keyed by this pause's own id,
   *  with its sha and message count — or the reason it wrote none. Stamped by
   *  the pause creators for the conversational loop's pause sites only; a
   *  workflow-step pause carries nothing here and resumes from
   *  `conversationHistory` as before. Optional for back-compat: a pause written
   *  before this field takes the snapshot path and says so. */
  checkpoint?: PauseCheckpointRef;
  perStepRecoveries: Record<string, number>;
  totalRecoveries: number;
  recoveryHistory: Array<{
    stepId: string;
    anomalyKind: string;
    decision: string;
    kind: 'fresh' | 'recovery_of_recovery';
  }>;
  /** Every completed step's output, keyed by step id — what `$.steps.<id>.<f>`
   *  reads.
   *
   *  Carried because the registry is rebuilt EMPTY on every entry into the
   *  loop, and a resume seeded only the cursor. So every reference across a
   *  pause boundary resolved to undefined, and the second half of a workflow
   *  ran on missing data while reporting ordinary tool errors.
   *
   *  For example, a run continued at s9, where s9 reads steps.s6 and s12 reads
   *  steps.s6 + steps.s8, all produced before the pause: those steps fail with
   *  "Cannot read properties of undefined", the recovery LLM cannot invent the
   *  missing data, and the run escalates with no report.
   *
   *  Optional for back-compat: a payload written before this field resumes as
   *  it did, which the resume-time reference check below turns into a loud
   *  failure rather than a silent one. */
  stepOutputs?: Record<string, unknown>;
  /** Steps the cursor entered, so end-of-graph accounting sees the whole run
   *  rather than only the half currently executing. Sets do not survive JSON. */
  enteredSteps?: string[];
  /** Steps that ran without producing their declared output, same reason. */
  unsatisfiedSteps?: string[];
  /** Where a LOOP step had got to, when the pause caught one mid-iteration.
   *
   *  A loop step is the only step that can be half done, and the park used to
   *  record a cursor one step PAST the loop it had abandoned — so the resumed
   *  run read a registry with no entry for it and refused to continue. Carried
   *  so the cursor can stay on the unfinished step and the loop pick up at the
   *  item it reached. Optional: a payload written before this field resumes by
   *  restarting the loop, which is what it did before. */
  loopPosition?: LoopPosition;
  /** Steps whose output a salvage turn produced from partial material, and
   *  what each was missing. Carried so the terminal result of a run that
   *  paused after a salvage still names the step, and so the later steps'
   *  prompts still carry the partial-material line after a resume. */
  salvagedSteps?: string[];
  salvageNotes?: Record<string, SalvageNote>;
  /** Per step, the mutating calls that step has already completed.
   *
   *  Carried because a pause RE-DISPATCHES the step it paused on — every HITL
   *  pause site here writes `resumeAfterStepId: currentStepId` and the resumed
   *  loop enters from it — so a step that wrote a document and then hit a gate on
   *  a later call runs again, whole, in another process. Without this the
   *  resumed attempt repeats the write, on exactly the long, interrupted runs
   *  most likely to repeat themselves. Bounded at serialisation: losing the
   *  pause would be worse than losing a replay (step-replay-ledger.ts). */
  stepReplay?: SerialisedStepReplay;
  pauseContext?: {
    originalQuestion: string;
    threadId: string;
  };
  /** Populated only when pauseReason === 'hitl_approval'. Carries the
   *  approvalId so the resume primitive can join back to the approval
   *  row, the pendingToolCalls so they can be dispatched after grant,
   *  and (for adapter-driven pauses only) the resume token + a snapshot
   *  of the conversation history so the model can be continued past the
   *  approved dispatch. */
  hitlContext?: {
    approvalId: string;
    pendingToolCalls: Array<{ id: string; name: string; input: Record<string, unknown> }>;
    gateReason: string;
    /** Approval-card summary (hitl-card-content.ts) carried so createHitlPause can
     *  surface it on the TaskExecutionResult → chat-turn `hitl_required` frame (MCP/web).
     *  Display-only; not used by the resume itself. Null when the flag is off. */
    actionSummary?: string | null;
    whySummary?: string | null;
    detail?: string | null;
    adapterResumeToken?: { adapterKind: string; serialized: string };
    /** Snapshot of the parent conversation at pause time. Carries tool_call /
     *  tool_result structure (toolCalls on assistant turns, toolCallId+toolName
     *  on tool turns) so the resume rebuild can push a coherent structured
     *  transcript — required for the §C3 delegate_task fan-out replay to land
     *  as a real assistant tool_use + user tool_result pair, not as prose. */
    conversationHistory?: Array<{
      role: 'user' | 'assistant' | 'tool';
      content: string;
      toolCallId?: string;
      toolName?: string;
      toolCalls?: Array<{ id: string; name: string; input: Record<string, unknown> }>;
    }>;
    provider?: ResolvedProvider;
    model?: string;
    /** Part C — set when the paused step was a workflow ADAPTER step
     *  (llm_reason / capability) that ran under an autonomous SDK session
     *  (invokeStepLLM persisted it on pause). A workflow-step pause has no
     *  `conversationHistory`, so this is what lets tryStructuredHitlResume engage
     *  for it: the resume restores the persisted session and CONTINUES the gated
     *  step's turn (the model re-attempts the gated call; canUseTool resolves it
     *  from the decision) instead of substituting the raw result on snapshot replay. */
    workflowStepSession?: boolean;
    /** Part 5 §C3 — snapshot of an in-flight delegate_task fan-out captured
     *  when pause_requested(hitl_gate) fires mid-fanout. reawaitInFlightDelegations
     *  rebuilds the DelegationResult[] from delegation_active rows after
     *  operator approval so the resumed conversation sees a coherent
     *  tool_result for the original delegate_task call. */
    inFlightDelegations?: {
      parentToolCallId: string;
      idempotencyKey: string;
      childInvocationIds: string[];
      taskSummaries: Array<{ agentId: string; objective: string; inputData?: Record<string, unknown> }>;
      deadlineAt: string;
    };
  };
  delegationContext?: {
    parentTaskId: string;
    parentToolCallId: string;
    childTaskIds: string[];
    deadlineAt: string;
    conversationHistory: NonNullable<HybridResumeState['hitlContext']>['conversationHistory'];
  };
  /** Populated only when pauseReason === 'self_wake'. Carries the wake spec + provenance so
   * resumeFromWake can rebuild + settle. Mirrors WakeContext (adapter/types.ts). */
  wakeContext?: {
    spec: import('./adapter/types').WakeSpec;
    originSurface?: import('./adapter/types').WakeOriginSurface;
    originTrust: 'trusted' | 'untrusted_inbound';
    threadRevision?: number;
    wakeChainDepth: number;
    /** ASI wake row id, stamped by createWakePause so resume joins back to the lease + trigger. */
    scheduledInvocationId?: string;
  };
}
