/**
 * Stamp every per-tool-call audit log row with the run's trust level so a
 * downstream consumer (harvest, security review, /activity UI) can filter
 * webhook-triggered actions without joining back to the invocation-start
 * row. Underscore-prefixed keys are reserved for executor metadata —
 * tool-call payload fields use the connector's own naming.
 */
function withTrustMetadata(
  context: Pick<ExecutionContext, 'trustLevel'>,
  payload: Record<string, unknown> | undefined,
): Record<string, unknown> {
  const base = payload ?? {};
  return {
    ...base,
    _trigger_trust_level: context.trustLevel ?? 'trusted',
  };
}

/** Stable HITL/audit name for a tool call. Empty connector ⇒ bare actionType
 *  so per-agent Slack tools and standard tools don't end up with the malformed
 *  `__name` key the previous code produced. Exported for unit testing. */
export function formatToolName(tc: { connector: string; actionType: string }): string {
  return tc.connector ? `${tc.connector}__${tc.actionType}` : tc.actionType;
}

// ── Recovery proposal scope ────────────────────────────────────────────────
//
// Recovery exists to get a specific, approved step past a failure. A proposal
// that calls a tool the graph never names and that writes somewhere is not a
// repair of that step; it is a new action nobody approved, taken by a model
// with the whole catalog in front of it. A read is different: looking
// something up to re-resolve an id or check a state is what "repair" plausibly
// needs. So the rule: a recovery proposal may call a tool the graph already
// names, or a read-only tool. Membership is on the FULL aliased catalog name
// (`gmail-1f2e__list_messages`), never the bare action, because two accounts of
// one connector share every bare action and must not be conflated.
//
// Instrumented first, enforced later. The classification below runs on every
// `continue` decision and is logged and audited whether or not enforcement is
// on, so the rule can be read against real proposals before it acts.
// TR_RECOVERY_SCOPE_ENFORCE=1 turns the rule into a refusal (as a unit, never
// in part) and narrows the advisor's catalog to the allowed set.

/** `TR_RECOVERY_SCOPE_ENFORCE=1`: a `continue` proposal with any call outside
 *  the allowed set executes nothing, and the advisor is only shown the allowed
 *  set. Default off, so the observation window runs on unchanged behaviour. */
export function isRecoveryScopeEnforced(): boolean {
  return process.env.TR_RECOVERY_SCOPE_ENFORCE === '1';
}

export interface RecoveryProposalCall {
  /** The full aliased catalog name when the call resolved; the formatted
   *  `<connector>__<actionType>` name when it did not, so an unresolvable
   *  proposal is identifiable rather than silent. */
  name: string;
  resolved: boolean;
  in_graph: boolean;
  read_only: boolean;
}

export interface RecoveryProposalScope {
  calls: RecoveryProposalCall[];
  /** Any call outside `in_graph ∪ read_only`. An unresolved call is outside. */
  outOfScope: boolean;
  unresolved: boolean;
  /** The names of the calls outside the set, in proposal order. */
  rejected: string[];
}

type CatalogEntryLike = { name: string; effect?: 'read' | 'write' | 'spawn'; categories?: string[] };

/** The catalog names the graph's own steps resolve to. A step's `toolName` is
 *  resolved the same way a call is, because a trigger-bound step is resolved
 *  at dispatch and its authored name may not be the catalog's. */
function recoveryGraphToolNames(
  workflowSteps: WorkflowStep[],
  tools: readonly CatalogEntryLike[],
): Set<string> {
  return new Set(
    workflowSteps
      .map((s) => s.toolName && (resolveCatalogTool(s.toolName, tools)?.name ?? s.toolName))
      .filter((n): n is string => typeof n === 'string' && n.length > 0),
  );
}

/** Classify a `continue` proposal's calls against the graph and the catalog. */
export function classifyRecoveryProposal(
  toolCalls: ReadonlyArray<{ connector: string; actionType: string }>,
  workflowSteps: WorkflowStep[],
  tools: readonly CatalogEntryLike[],
): RecoveryProposalScope {
  const graphNames = recoveryGraphToolNames(workflowSteps, tools);
  const calls = toolCalls.map((call): RecoveryProposalCall => {
    const formatted = formatToolName(call);
    const entry = resolveCatalogTool(formatted, tools);
    const resolvedName = entry?.name ?? formatted;
    const in_graph = entry !== undefined && graphNames.has(entry.name);
    const read_only = entry !== undefined && toolIsReadOnly(entry);
    return { name: resolvedName, resolved: entry !== undefined, in_graph, read_only };
  });
  const rejected = calls.filter((c) => !(c.in_graph || c.read_only)).map((c) => c.name);
  return {
    calls,
    outOfScope: rejected.length > 0,
    unresolved: calls.some((c) => !c.resolved),
    rejected,
  };
}

/** The catalog entries recovery may propose: the graph's own tools plus every
 *  read-only tool. What the advisor is shown once enforcement is on. */
export function allowedRecoveryTools<T extends CatalogEntryLike>(
  workflowSteps: WorkflowStep[],
  tools: readonly T[],
): T[] {
  const graphNames = recoveryGraphToolNames(workflowSteps, tools);
  return tools.filter((t) => graphNames.has(t.name) || toolIsReadOnly(t));
}

